    for(int i=0;i<16;++i)ToggleFavorite(palette,RGB(i,2,3));check(!ToggleFavorite(palette,RGB(99,2,3))&&palette.favorites.size()==16,"favorite limit rejects a17th without removing another");check(ToggleFavorite(palette,RGB(3,2,3))&&ToggleFavorite(palette,RGB(99,2,3))&&palette.favorites.back()==RGB(99,2,3),"unfavorite frees one slot and preserves favorite order");
    CString error;const CString encoded=EncodePalette(palette);PaletteData decoded;check(DecodePalette(encoded,decoded,error)&&decoded.favorites==palette.favorites&&decoded.recent==palette.recent,"bounded favorites/recent round trip losslessly");
    for(auto value:{L"bad",L"123456|12345",L"123456,123456|",L"123456,|",L"|123456,",L"||",L"000000|\nHotkey0=0,44"}){const auto before=decoded;check(!DecodePalette(value,decoded,error)&&decoded.favorites==before.favorites&&decoded.recent==before.recent,"malformed/injected/duplicate palette data is rejected transactionally");}
    check(DecodePalette(L"",decoded,error)&&decoded.favorites.empty()&&decoded.recent.empty(),"old INIs with no palette keep fixed defaults");
